inline constexpr fusion::Net kCritic{critic_layers, 4, 23};
inline int32_t quantize(float x) {          // training.meow_rl.quant.quantize_input: floor(x * 2^12 + 1/2), +-16384
    double v = std::floor(double(x) * 4096.0 + 0.5);
    return int32_t(v < -16384.0 ? -16384.0 : v > 16384.0 ? 16384.0 : v);
}
inline const char* kernel_name() { return fusion::kernel::name(); }
inline double value(const float* f) {
    int32_t x[416], acc[1];
    for (int i = 0; i < 416; i++) x[i] = quantize(f[i]);
    fusion::forwardRaw(kCritic, x, acc);
    return std::ldexp(double(acc[0]), -kCritic.outExp);
}
